import sympy

class Foo:
    def __eq__(self, other):
        if isinstance(other, sympy.Basic):
            return True
        return NotImplemented
    def __ne__(self, other):
        return not self == other

f = Foo()
s = sympy.Symbol('x')
print('f==s', f==s)
print('s==f', s==f)
print('s.__eq__(f)', s.__eq__(f))
print('s"'!=f'"', s"'!=f)
print('"'pi==f', sympy.pi==f)
print('oo==f', sympy.oo==f)
print('s<f?', end=' ')
try:
    print(s < f)
except Exception as e:
    print(type(e).__name__, e)

class FooOrd:
    def __gt__(self, other):
        if isinstance(other, sympy.Basic):
            return True
        return NotImplemented

fo = FooOrd()
print('s < FooOrd', s < fo)
